entries[12835] = { ["name"] = "Pläne: Vernichter", ["text"] = "Benötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Vernichters.\nVerkaufspreis:\nVernichter\nWird beim Anlegen gebunden\nWaffenhand Axt\n49 - 92 Schaden Tempo 1.70\n(41.47 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 58\nTrefferchance: Rüstung eines Feindes um 200 verringert. Ergänzt sich bis zu dreimal.\nVerkaufspreis:\nBenötigt Thoriumbarren (40), Arkanitbarren (12), Essenz des Untodes (10), Gewaltiger Smaragd (8), Verdichteter Schleifstein (2), Verzaubertes Leder (4)" }
entries[12836] = { ["name"] = "Pläne: Frostwache", ["text"] = "Benötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung von Frostwache.\nVerkaufspreis:\nFrostwache\nWird beim Anlegen gebunden\nWaffenhand Schwert\n66 - 124 Schaden Tempo 2.30\n(41.30 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nBenötigt Stufe 58\nTrefferchance: Bewegungstempo des Ziels um 30% verlangsamt und Zeit zwischen Angriffen um 25% erhöht. Hält 5 Sek. lang an.\nVerkaufspreis:\nBenötigt Arkanitbarren (18), Blauer Saphir (8), Azerothischer Diamant (8), Essenz des Wassers (4), Verdichteter Schleifstein (2), Verzaubertes Leder (4)" }
