entries[13308] = { ["name"] = "Bauplan: Eisdeflektor", ["text"] = "Benötigt Ingenieurskunst (155)\nBenutzen: Lehrt Euch die Herstellung eines Eisdeflektors.\nVerkaufspreis:\nEisdeflektor\nBenötigt Stufe 21\nBenutzen: Absorbiert 600 Frostschaden. Hält 1 Min. lang an. (15 Min Abklingzeit)\n5 Aufladungen\nVerkaufspreis:\nBenötigt Surrendes bronzenes Dingsda , Frostöl" }
entries[13309] = { ["name"] = "Bauplan: Liebevoll hergestelltes Schießeisen", ["text"] = "Benötigt Ingenieurskunst (120)\nBenutzen: Lehrt Euch die Herstellung eines liebevoll hergestellten Schießeisens.\nVerkaufspreis:\nLiebevoll hergestelltes Schießeisen\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n16 - 31 Schaden Tempo 1.80\n(13.06 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\nBenötigt Stufe 19\nVerkaufspreis:\nBenötigt Bronzeröhre (2), Eine Hand voll Kupferbolzen (2), Schwerer Griff , Moosachat (3)" }
entries[13310] = { ["name"] = "Bauplan: Genaues Zielfernrohr", ["text"] = "Benötigt Ingenieurskunst (180)\nBenutzen: Lehrt Euch die Herstellung eines genauen Zielfernrohrs.\nVerkaufspreis:\nGenaues Zielfernrohr\nBenötigt Stufe 20\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 3.\nVerkaufspreis:\nBenötigt Bronzeröhre , Jade , Citrin" }
entries[13311] = { ["name"] = "Bauplan: Mechanischer Drachling", ["text"] = "Benötigt Ingenieurskunst (200)\nBenutzen: Lehrt Euch die Herstellung eines mechanischen Drachlings.\nVerkaufspreis:\nMechanischer Drachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 30\nBenötigt Ingenieurskunst (200)\nBenutzen: Aktiviert Euren mechanischen Drachling, 1 Min. lang für Euch zu kämpfen. (20 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Bronzegerüst , Eisenstrebe (4), Gyrochronatom (4), Citrin (2), Verschmorte Verkabelung" }
