entries[13508] = { ["name"] = "Auge von Arachnida", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, ist jedoch sehr zerbrechlich. (1 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[13509] = { ["name"] = "Klammer der Voraussicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Kontert das Zauberwirken des Feindes und verhindert 10 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung. Es besteht die Chance eines Fehlschlags, wenn das Ziel über Stufe 60 ist. (1 Min Abklingzeit)\nVerkaufspreis:" }
